const capability={version:2,stages:[{id:"stage_1",io:{"reads":{"input":["rank"],"state":[]},"writes":{"state":["targets.__actedOn"],"output":[]}},navigation:"optional",async run({input,waitForTarget,waitUntil,settle}){const rank=input["rank"];if(typeof rank!=="number"||rank<1){throw new Error("Invalid rank: must be a positive number")}const cssSelector=`#current-hotlist > div:nth-of-type(2) > div:nth-of-type(3) > div > div:nth-of-type(${rank}) > div`;const element=await waitForTarget({strategies:[{type:"css",value:cssSelector}]});const actedOn=(element.innerText||element.textContent||"").replace(/\s+/gu," ").trim().slice(0,240);element.click();await waitUntil(()=>{const dialog=document.querySelector('[role="dialog"]');return dialog!==null});await settle();return{outcome:"Continue",state:{targets:{__actedOn:actedOn}}}}},{id:"stage_verify",io:{"reads":{"input":["rank"],"state":["targets.__actedOn"]},"writes":{"state":[],"output":["currentRank","heat","targetTitle","targetUrl"]}},navigation:"none",async run({input,state,waitUntil,settle,identityMatches}){const actedOn=state.targets?.__actedOn;if(!actedOn){throw new Error("Missing __actedOn from previous stage")}await waitUntil(()=>{const dialog2=document.querySelector('[role="dialog"]');if(!dialog2)return false;const heading2=dialog2.querySelector("h1, h2, h3, h4, h5, h6");return heading2&&heading2.innerText.trim().length>0});await settle();const dialog=document.querySelector('[role="dialog"]');if(!dialog){throw new Error("Dialog not found after click")}const heading=dialog.querySelector("h1, h2, h3, h4, h5, h6");if(!heading){throw new Error("No heading found in dialog")}const targetTitle=heading.innerText.trim();if(!identityMatches(actedOn,targetTitle)){throw new Error(`Identity mismatch: actedOn="${actedOn.slice(0,50)}..." vs title="${targetTitle}"`)}const targetUrl=location.href;const dialogText=dialog.innerText;const rankMatch=dialogText.match(/第\s*(\d+)\s*名/);const currentRank=rankMatch?parseInt(rankMatch[1],10):null;const heatMatch=dialogText.match(/(\d+\.?\d*万)/);const heat=heatMatch?heatMatch[1]:null;if(!targetTitle||!targetUrl){throw new Error("Missing required output fields")}const output={targetTitle,targetUrl,currentRank:currentRank??input["rank"],heat:heat||""};return{outcome:"Success",output,evidence:[{kind:"status",value:{url:targetUrl,title:targetTitle,hasDialog:true}}]}}}]};export{capability};